from pathlib import Path
from fastapi import FastAPI, Header, HTTPException, Query
from fastapi.responses import FileResponse
from app.common.export_jobs import export_queue
from app.financing.service import list_applications
from app.repayment.service import build_schedule

app = FastAPI(title="AI R&D System Demo", version="0.1.0")
_STATIC = Path(__file__).resolve().parent.parent / "static" / "index.html"

@app.get("/")
def home():
    return FileResponse(_STATIC)

@app.get("/api/financing-applications")
def financing_applications(
    page: int = Query(1, ge=1),
    page_size: int = Query(5, ge=1, le=100),
    x_user: str = Header("alice"),
):
    try:
        return list_applications(user=x_user, page=page, page_size=page_size)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

@app.get("/api/repayment-schedule")
def repayment_schedule(
    total_amount: float = Query(..., description="放款金额"),
    periods: int = Query(..., description="期数"),
):
    try:
        installments = build_schedule(total_amount=total_amount, periods=periods)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"total_amount": total_amount, "periods": periods, "installments": installments}

@app.get("/api/export-jobs/{job_id}")
def get_export_job(job_id: str):
    job = export_queue.get(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="job not found")
    return job.as_dict()
# 融资申请与还款计划

放款业务的最小基础工程：融资申请列表（分页 + 数据权限）和还款计划生成。

```bash
../../.venv/bin/python -m pytest -q
../../.venv/bin/python -m uvicorn app.main:app --port 8000
```

模块：

- `app/financing/`：融资申请列表，按 `X-User` 做 tenant 权限过滤，复用 `app/common/pagination.py`。
- `app/repayment/`：还款计划，把放款金额按 `periods` 期均摊，通过 `/api/repayment-schedule` 暴露。
- `app/common/`：分页、权限、异步导出队列等公共模块。
